// Shot motion matching (v5.6, cfg.MM): C# twin of the pose.ts block "shot motion matching" (mmType / mmRow / mmLoad
// and the clip() branch). Tables in Pose.MM.Gen.cs (generated by scripts/ml/bake_shot.ts from the same model as
// src/core/mmshot.ts). Arithmetic only (no transcendental calls), same operation order as TS -> identical bits.
using System;
using static Hoops.Core.Util;
using static Hoops.Core.Data;
using static Hoops.Core.Sim;

namespace Hoops.Core
{
    public static partial class Pose
    {
        // MM_TYPES order: cs, pull, deep, fade, step, quick
        const int MM_CS = 0, MM_PULL = 1, MM_DEEP = 2, MM_FADE = 3, MM_STEP = 4, MM_QUICK = 5;

        /// <summary>Which learned table a shot uses (-1 = the classic clip). Jumpers only; stateless.</summary>
        public static int mmType(Player p)
        {
            if (cfg.MM == 0 || cfg.PRO == 0) return -1;
            string kind = CKof(p.sv);
            if (kind == "quick") return MM_QUICK;
            if (kind == "fade") return MM_FADE;
            if (kind == "step") return MM_STEP;
            if (kind != "jump" && kind != "mshot") return -1;
            if (p.sqn == 3 || p.sqn == 4) return MM_PULL;
            return Hypot(hoop(p.tm) - p.x, HY - p.y) >= 265 ? MM_DEEP : MM_CS;
        }

        /// <summary>Uniform Catmull-Rom over one baked row (k clamped to 0..1).</summary>
        static double mmRow(double[] r, double k)
        {
            double u = Math.Min(1, Math.Max(0, k)) * (MM_KB - 1);
            int i = Math.Min(MM_KB - 2, (int)Math.Floor(u));
            double f = u - i,
                p0 = r[i > 0 ? i - 1 : 0],
                p1 = r[i],
                p2 = r[i + 1],
                p3 = r[i + 2 < MM_KB ? i + 2 : MM_KB - 1];
            return p1 + 0.5 * f * (p2 - p0 + f * (2 * p0 - 5 * p1 + 4 * p2 - p3 + f * (3 * (p1 - p2) + p3 - p0)));
        }

        /// <summary>The player's load on the learned form axis (deeper dip / more leg; bigs flick it).</summary>
        public static double mmLoad(Player p)
        {
            var g = p.sg ?? NOFORM;
            double ht = T(p.ht) ? p.ht : 6.5;
            return clamp(((Or0(g.dp) - 0.225) / 0.225) * 0.7 + ((Or0(g.k) - 0.08) / 0.08) * 0.3 - (ht - 6.6) * 0.6, -1.5, 1.5);
        }

        /// <summary>Fill the clip output from table mt at phase k (CLIPK channels + hR, hL).</summary>
        static void mmClip(Player p, int mt, double k, Q o)
        {
            var T0 = MM_T[mt];
            double L = mmLoad(p),
                km = mt == MM_QUICK ? (k <= 0.46 ? (k * 0.7) / 0.46 : 0.7 + ((k - 0.46) / 0.54) * 0.3) : k; // (quick release warped onto key .7)
            for (int j = 0; j < 20; j++)
            {
                double v = mmRow(T0[j], km) + L * mmRow(MM_DLOAD[j], km);
                if (j < 18) o[CLIPI[j]] = v;
                else if (j == 18) o.hR = v;
                else o.hL = v;
            }
        }
    }
}
